cd /workspace/submission && python3 - <<'PY'
import exact, random, math, copy, json, heapq
# simple multi-path fabric
prof={'groups':2,'jitter_ps':[0,0],'measurements':[[0,1,0,0]]}
fabric={'n':2,'interval_ns':1,'slice_ns':100,'offset_ns':0,'drift_ppb':[0,0],'heat':[],'anchors':[[0,0,10]],'links':[
 {'ends':[[0,0,0],[1,0,1]],'delay_ns':[1,2],'defer_rounds':[0,0]},
 {'ends':[[0,1,0],[1,1,1]],'delay_ns':[1,2],'defer_rounds':[0,0]},
],'slices':[[0,1]],'blackouts':[],'guards_ns':[0,100],'reconfig_ns':0}
cal=exact.solve_calibration(prof);fab=exact.Fabric(fabric);art=exact.make_plan_artifact(fab,cal)
print(json.dumps({k:v for k,v in art.items() if k not in ('profile','bounds_as','age_rounds','pred')},indent=1))
print('P',fab.P,'audit',exact.audit_plan(prof,fabric,art))
# Try alternate predecessor for each msg cell if another edge from same/different prev delivers same pair.
b=art['bounds_as'];a=art['age_rounds'];pr=art['pred']
for p in range(fab.P):
 for i in range(fab.n):
  cell=pr[p][i]
  if cell is None: continue
  pv,kind=cell; node=pv%fab.n; pp=pv//fab.n
  # enumerate any predecessor finite vertex with eligible outgoing edge to this cell giving exact labels
  opts=[]
  for pv2 in range(fab.V):
   pp2=pv2//fab.n; i2=pv2%fab.n
   if b[pp2][i2] is None: continue
   # local
   if i2==i and (pp2+1)%fab.P==p:
    cb=fab.eff[pv2]*fab.T
    if b[p][i]==b[pp2][i2]+cb and a[p][i]==a[pp2][i2]+1:opts.append([pv2,-1])
   for e in fab.message_adjacency(cal,min(fab.guards))[pv2]:
    if e[2]<art['guard_ns']:continue
    dv=e[0];q=dv//fab.n;ii=dv%fab.n
    if q==p and ii==i:
     cb=e[1]//fab.base;ca=e[1]%fab.base
     if b[p][i]==b[pp2][i2]+cb and a[p][i]==a[pp2][i2]+ca:opts.append([pv2,e[3]])
  if opts and opts[0]!=cell:
   alt=copy.deepcopy(art);alt['pred'][p][i]=opts[0]
   print('mutating',p,i,cell,'->',opts[0],'valid?',exact.audit_plan(prof,fabric,alt))
   raise SystemExit
print('no alt found')
PY
